    97	async function handleUndo() {
    98	  console.log('[Undo] Undo requested, operations:', getState().operations.length);
    99	  const ops = popOperation();
   100	  if (!ops) { showToast('Nothing to undo', 'info'); return; }
   101	
   102	  if (ops.length === 0) {
   103	    // Revert to original
   104	    const { originalGif } = getState();
   105	    const meta = parseGifInfo(originalGif);
   106	    setState({ currentGif: originalGif, meta });
