   110	    return;
   111	  }
   112	
   113	  // Check for a checkpoint close to the target
   114	  const { checkpoints, originalGif } = getState();
   115	  let startIdx = 0;
   116	  let startGif = originalGif;
   117	
   118	  for (const [cpIdx, cpData] of checkpoints) {
   119	    if (cpIdx < ops.length && cpIdx >= startIdx) {
   120	      startIdx = cpIdx + 1;
   121	      startGif = cpData;
   122	    }
   123	  }
   124	
   125	  showProcessing('Undoing…');
   126	  try {
   127	    let current = startGif;
   128	    // Replay operations from startIdx to ops.length - 1
   129	    for (let i = startIdx; i < ops.length; i++) {
   130	      current = await replayOperation(current, ops[i]);
   131	    }
