    87	/** Avoid collisions inside the zip: "cat.gif", "cat-2.gif", "cat-3.gif"… */
    88	function uniqueName(name) {
    89	  const taken = new Set(items.map((i) => i.name.toLowerCase()));
    90	  if (!taken.has(name.toLowerCase())) return name;
    91	
    92	  const dot = name.lastIndexOf('.');
    93	  const base = dot > 0 ? name.slice(0, dot) : name;
    94	  const ext = dot > 0 ? name.slice(dot) : '';
    95	  let n = 2;
    96	  while (taken.has(`${base}-${n}${ext}`.toLowerCase())) n++;
    97	  return `${base}-${n}${ext}`;
    98	}
