     9	export async function extractFrames(gifData) {
    10	  await initFFmpeg();
    11	  await writeFile('input.gif', gifData);
    12	  await runFFmpeg(extractFramesCmd('input.gif', 'frame_%04d.png'));
    13	
    14	  const frames = [];
    15	  for (let i = 1; ; i++) {
    16	    const name = `frame_${String(i).padStart(4, '0')}.png`;
    17	    try {
    18	      const data = await readFile(name);
    19	      const blob = new Blob([data], { type: 'image/png' });
    20	      frames.push({ index: i, blob, url: URL.createObjectURL(blob) });
    21	      await deleteFile(name);
    22	    } catch {
    23	      break;
    24	    }
    25	  }
    26	  await deleteFile('input.gif');
    27	  return frames;
    28	}
