   221	    startMouseY = e.clientY - rect.top;
   222	    const crop = getCropRect();
   223	    startCropX = crop.x; startCropY = crop.y;
   224	    startCropW = crop.w; startCropH = crop.h;
   225	
   226	    mode = hitTest(startMouseX, startMouseY);
   227	    if (mode === 'move') canvas.style.cursor = 'grabbing';
   228	  });
   229	
   230	  canvas.addEventListener('mousemove', (e) => {
   231	    const rect = canvas.getBoundingClientRect();
   232	    const curX = e.clientX - rect.left;
   233	    const curY = e.clientY - rect.top;
   234	
   235	    if (!mode) {
   236	      updateCursor(curX, curY);
   237	      return;
   238	    }
   239	
   240	    const m = getImageMapping();
   241	    const dx = (curX - startMouseX) * m.scaleX;
   242	    const dy = (curY - startMouseY) * m.scaleY;
   243	
   244	    if (mode === 'move') {
   245	      const newX = Math.max(0, Math.min(m.meta.width - startCropW, startCropX + dx));
   246	      const newY = Math.max(0, Math.min(m.meta.height - startCropH, startCropY + dy));
   247	      setCropRect(newX, newY, startCropW, startCropH);
   248	    } else if (mode === 'draw') {
   249	      const { gx: gx1, gy: gy1 } = canvasToGif(startMouseX, startMouseY);
   250	      const { gx: gx2, gy: gy2 } = canvasToGif(curX, curY);
   251	      const x = Math.max(0, Math.min(gx1, gx2));
   252	      const y = Math.max(0, Math.min(gy1, gy2));
   253	      const w = Math.min(m.meta.width - x, Math.abs(gx2 - gx1));
   254	      const h = Math.min(m.meta.height - y, Math.abs(gy2 - gy1));
   255	      setCropRect(x, y, w, h);
   256	    } else if (mode.startsWith('resize-')) {
   257	      let x = startCropX, y = startCropY, w = startCropW, h = startCropH;
   258	      if (mode.includes('r')) { w = Math.max(1, startCropW + dx); }
   259	      if (mode.includes('l')) { x = startCropX + dx; w = startCropW - dx; }
   260	      if (mode.includes('b')) { h = Math.max(1, startCropH + dy); }
   261	      if (mode.includes('t')) { y = startCropY + dy; h = startCropH - dy; }
   262	      if (w < 1) { w = 1; }
   263	      if (h < 1) { h = 1; }
   264	      setCropRect(x, y, w, h);
   265	    }
   266	  });
