   268	  canvas.addEventListener('mouseup', () => {
   269	    mode = null;
   270	    canvas.style.cursor = 'crosshair';
   271	  });
   272	
   273	  canvas.addEventListener('mouseleave', () => {
   274	    mode = null;
   275	    canvas.style.cursor = 'crosshair';
   276	  });
   277	}
