   279	function drawCropOverlay() {
   280	  const canvas = document.getElementById('crop-canvas');
   281	  if (!canvas || canvas.classList.contains('hidden')) return;
   282	
   283	  const ctx = canvas.getContext('2d');
   284	  const img = document.getElementById('preview-img');
   285	  const { meta } = getState();
   286	
   287	  const imgRect = img.getBoundingClientRect();
   288	  const canvasRect = canvas.getBoundingClientRect();
   289	  const offX = imgRect.left - canvasRect.left;
   290	  const offY = imgRect.top - canvasRect.top;
   291	  const scaleX = imgRect.width / meta.width;
   292	  const scaleY = imgRect.height / meta.height;
   293	
   294	  const cx = parseInt(document.getElementById('crop-x')?.value || 0);
   295	  const cy = parseInt(document.getElementById('crop-y')?.value || 0);
   296	  const cw = parseInt(document.getElementById('crop-w')?.value || meta.width);
   297	  const ch = parseInt(document.getElementById('crop-h')?.value || meta.height);
   298	
   299	  ctx.clearRect(0, 0, canvas.width, canvas.height);
   300	
   301	  // Dim outside crop
   302	  ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
   303	  ctx.fillRect(0, 0, canvas.width, canvas.height);
   304	
   305	  // Clear crop area
   306	  const drawX = offX + cx * scaleX;
   307	  const drawY = offY + cy * scaleY;
   308	  const drawW = cw * scaleX;
   309	  const drawH = ch * scaleY;
   310	  ctx.clearRect(drawX, drawY, drawW, drawH);
   311	
   312	  // Crop border
   313	  ctx.strokeStyle = '#818cf8';
   314	  ctx.lineWidth = 2;
   315	  ctx.strokeRect(drawX, drawY, drawW, drawH);
   316	
   317	  // Corner handles
   318	  const hs = 6;
   319	  ctx.fillStyle = '#818cf8';
   320	  for (const [hx, hy] of [[drawX, drawY], [drawX + drawW, drawY], [drawX, drawY + drawH], [drawX + drawW, drawY + drawH]]) {
   321	    ctx.fillRect(hx - hs / 2, hy - hs / 2, hs, hs);
   322	  }
   323	}
