     1	/** Lightweight pub/sub state store */
     2	
     3	const MAX_UNDO_OPERATIONS = 20;
     4	const CHECKPOINT_CACHE_SIZE = 3;
     5	
     6	const initialState = {
     7	  /** @type {Uint8Array|null} original GIF bytes (never mutated) */
     8	  originalGif: null,
     9	  /** @type {Uint8Array|null} current GIF bytes after edits */
    10	  currentGif: null,
    11	  /** @type {string|null} original filename of the loaded GIF */
    12	  fileName: null,
    13	  /** @type {string|null} object URL for preview */
    14	  previewUrl: null,
    15	  /** GIF metadata */
    16	  meta: { width: 0, height: 0, frames: 0, duration: 0, size: 0 },
    17	  /** @type {Array<{tool: string, params: object}>} operation history for undo */
    18	  operations: [],
    19	  /** @type {Map<number, Uint8Array>} blob checkpoints keyed by operation index */
    20	  checkpoints: new Map(),
    21	  /** @type {string|null} currently active tool */
    22	  activeTool: null,
    23	  /** whether FFmpeg is currently processing */
    24	  processing: false,
    25	  /** whether FFmpeg is loaded */
    26	  ffmpegReady: false,
    27	};
    28	
    29	let state = { ...initialState, checkpoints: new Map() };
    30	const listeners = new Map();
    31	
    32	export function getState() {
    33	  return state;
    34	}
    35	
    36	export function setState(partial) {
    37	  const prev = { ...state };
    38	  Object.assign(state, partial);
    39	
    40	  for (const [key, cbs] of listeners) {
    41	    if (key in partial) {
    42	      for (const cb of cbs) cb(state[key], prev[key]);
    43	    }
    44	  }
    45	  // wildcard listeners
    46	  if (listeners.has('*')) {
    47	    for (const cb of listeners.get('*')) cb(state, prev);
    48	  }
    49	}
    50	
    51	export function subscribe(key, cb) {
    52	  if (!listeners.has(key)) listeners.set(key, new Set());
    53	  listeners.get(key).add(cb);
    54	  return () => listeners.get(key).delete(cb);
    55	}
    56	
    57	export function revokePreview() {
    58	  if (state.previewUrl) {
    59	    URL.revokeObjectURL(state.previewUrl);
    60	    setState({ previewUrl: null });
    61	  }
    62	}
    63	
    64	export function setPreviewFromGif(gifBytes) {
    65	  revokePreview();
    66	  const blob = new Blob([gifBytes], { type: 'image/gif' });
    67	  setState({ previewUrl: URL.createObjectURL(blob) });
    68	}
    69	
    70	/** Push an operation to the undo stack */
    71	export function pushOperation(tool, params, resultGif) {
    72	  const ops = [...state.operations, { tool, params }];
    73	  if (ops.length > MAX_UNDO_OPERATIONS) {
    74	    ops.shift();
    75	    // shift checkpoints too
    76	    const newCheckpoints = new Map();
    77	    for (const [idx, data] of state.checkpoints) {
    78	      if (idx > 0) newCheckpoints.set(idx - 1, data);
    79	    }
    80	    state.checkpoints = newCheckpoints;
    81	  }
    82	
    83	  // Cache checkpoint every few operations for faster undo
    84	  const checkpoints = new Map(state.checkpoints);
    85	  if (ops.length % Math.ceil(MAX_UNDO_OPERATIONS / CHECKPOINT_CACHE_SIZE) === 0) {
    86	    // Keep only CHECKPOINT_CACHE_SIZE most recent
    87	    if (checkpoints.size >= CHECKPOINT_CACHE_SIZE) {
    88	      const oldest = Math.min(...checkpoints.keys());
    89	      checkpoints.delete(oldest);
    90	    }
    91	    checkpoints.set(ops.length - 1, resultGif);
    92	  }
    93	
    94	  setState({ operations: ops, currentGif: resultGif, checkpoints });
    95	  setPreviewFromGif(resultGif);
    96	}
    97	
    98	/** Pop the last operation (undo) */
    99	export function popOperation() {
   100	  if (state.operations.length === 0) return null;
   101	  const ops = state.operations.slice(0, -1);
   102	  setState({ operations: ops });
   103	  return ops;
   104	}
   105	
   106	export function resetState() {
   107	  revokePreview();
   108	  state = { ...initialState, checkpoints: new Map() };
   109	}

