785	    10	/**
786	    11	 * Iteratively compress a GIF to fit Slack emoji requirements:
787	    12	 * square, ≤128KB. Tries progressively more aggressive settings.
788	    13	 */
789	    14	export async function slackEmojiExport(gifData) {
790	    15	  await initFFmpeg();
791	    16	
792	    17	  for (const size of SIZE_STEPS) {
793	    18	    for (const colors of COLOR_STEPS) {
794	    19	      for (const fps of FPS_STEPS) {
795	    20	        const result = await runTwoPass(gifData, { size, colors, fps });
796	    21	        if (result.byteLength <= TARGET_SIZE) {
797	    22	          return result;
798	    23	        }
799	    24	      }
800	    25	    }
801	    26	  }
802	    27	
803	    28	  // Return the most aggressively compressed version even if over target
804	    29	  const lastSize = SIZE_STEPS[SIZE_STEPS.length - 1];
805	    30	  const lastColors = COLOR_STEPS[COLOR_STEPS.length - 1];
806	    31	  const lastFps = FPS_STEPS[FPS_STEPS.length - 1];
807	    32	  return await runTwoPass(gifData, { size: lastSize, colors: lastColors, fps: lastFps });
808	    33	}
