    18	
    19	/**
    20	 * Compress via two-pass palette optimization.
    21	 * Returns [pass1Args, pass2Args] — caller must run both sequentially.
    22	 */
    23	export function compressCmds(inputFile, outputFile, { colors = 256, fps = null } = {}) {
    24	  const filters = [];
    25	  if (fps) filters.push(`fps=${fps}`);
    26	
    27	  const pass1Filters = [...filters, `palettegen=max_colors=${colors}:stats_mode=diff`].join(',');
    28	  const pass2Filters = [...filters, `paletteuse=dither=bayer:bayer_scale=5`].join(',');
    29	
    30	  const pass1 = ['-i', inputFile, '-vf', pass1Filters, '-y', 'palette.png'];
    31	  const pass2 = ['-i', inputFile, '-i', 'palette.png', '-lavfi', pass2Filters, '-y', outputFile];
    32	  return [pass1, pass2];
    33	}
    34	
    35	export function speedCmd(inputFile, outputFile, speed) {
    36	  const pts = 1 / speed;
    37	  return [
    38	    '-i', inputFile,
    39	    '-vf', `setpts=${pts.toFixed(4)}*PTS`,
    40	    '-y', outputFile,
    41	  ];
    42	}
    43	
    44	export function trimCmd(inputFile, outputFile, startTime, duration) {
    45	  const args = ['-i', inputFile];
    46	  if (startTime > 0) args.push('-ss', String(startTime));
    47	  if (duration > 0) args.push('-t', String(duration));
    48	  args.push('-y', outputFile);
    49	  return args;
    50	}
    51	
    52	export function reverseCmd(inputFile, outputFile) {
    53	  return [
    54	    '-i', inputFile,
    55	    '-vf', 'reverse',
    56	    '-y', outputFile,
    57	  ];
