     1	/**
     2	 * Parse GIF binary to extract metadata without FFmpeg.
     3	 * Reads the GIF89a/GIF87a header, logical screen descriptor, and
     4	 * walks extension blocks to count frames and gather delays.
     5	 */
     6	export function parseGifInfo(data) {
     7	  if (data.byteLength < 13) {
     8	    return { width: 0, height: 0, frames: 0, duration: 0, delays: [], size: data.byteLength };
     9	  }
    10	
    11	  const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
    12	  const width = view.getUint16(6, true);
    13	  const height = view.getUint16(8, true);
    14	
    15	  let frames = 0;
    16	  let totalDelay = 0;
    17	  const delays = [];
    18	
    19	  // Skip header (13 bytes) + global color table
    20	  const packed = data[10];
    21	  const hasGCT = (packed >> 7) & 1;
    22	  const gctSize = hasGCT ? 3 * (1 << ((packed & 0x07) + 1)) : 0;
    23	  let offset = 13 + gctSize;
    24	
    25	  try {
    26	    while (offset < data.length - 1) {
    27	      const block = data[offset];
    28	
    29	      if (block === 0x3b) break; // trailer
    30	
    31	      if (block === 0x21) {
    32	        // extension
    33	        const label = data[offset + 1];
    34	        if (label === 0xf9 && offset + 7 < data.length) {
    35	          // graphic control extension
    36	          const delay = view.getUint16(offset + 4, true) * 10; // centiseconds -> ms
    37	          delays.push(delay || 100); // default 100ms if 0
    38	          totalDelay += delay || 100;
    39	          offset += 8; // fixed size block
    40	        } else {
    41	          // skip other extensions
    42	          offset += 2;
    43	          while (offset < data.length) {
    44	            const sz = data[offset];
    45	            if (sz === 0) { offset++; break; }
    46	            offset += sz + 1;
    47	          }
    48	        }
    49	      } else if (block === 0x2c) {
    50	        // image descriptor
    51	        frames++;
    52	        if (offset + 10 >= data.length) break;
    53	        const imgPacked = data[offset + 9];
    54	        const hasLCT = (imgPacked >> 7) & 1;
    55	        const lctSize = hasLCT ? 3 * (1 << ((imgPacked & 0x07) + 1)) : 0;
    56	        offset += 10 + lctSize;
    57	        if (offset >= data.length) break;
    58	        offset++; // LZW minimum code size
    59	        // skip sub-blocks
    60	        while (offset < data.length) {
    61	          const sz = data[offset];
    62	          if (sz === 0) { offset++; break; }
    63	          offset += sz + 1;
    64	        }
    65	      } else {
    66	        offset++;
    67	      }
    68	    }
    69	  } catch {
    70	    // If parsing fails partway, return what we have so far
    71	  }
    72	
    73	  return {
    74	    width,
    75	    height,
    76	    frames: Math.max(frames, 1),
    77	    duration: totalDelay,
    78	    delays,
    79	    size: data.byteLength,
    80	  };
    81	}
=== README.md
     1	# GIF Editor
     2	
     3	A client-side GIF editor that runs entirely in the browser. No uploads, no servers — your files never leave your machine.
     4	
     5	**Live:** [https://abhisingh.in/gif-editor/](https://abhisingh.in/gif-editor/)
     6	
     7	## Features
     8	
     9	- **Resize** — scale with aspect ratio lock and quick presets (25%, 50%, 75%, 200%)
    10	- **Crop** — interactive drag-to-draw, move, and corner-resize crop area with ratio presets (1:1, 4:3, 16:9)
    11	- **Compress** — reduce colors (8–256) and FPS with two-pass palette optimization
    12	- **Speed** — adjust playback speed from 0.25× to 4×
    13	- **Trim** — cut start/end by time
    14	- **Reverse** — reverse frame order
    15	- **Frame Editing** — extract frames, delete or drag-to-reorder, reassemble at custom FPS
    16	- **Filters** — brightness, contrast, saturation, grayscale with presets
    17	- **Slack Emoji Export** — one-click preset that center-crops to square and iteratively compresses to ≤128 KB
    18	- **Batch Slack Export** — drop several GIFs at once and download them all Slack-ready in one `.zip`, with original filenames kept
    19	
    20	## Tech Stack
    21	
    22	- **Vanilla JS** (ES modules) — no framework
    23	- **Tailwind CSS v4** — via `@tailwindcss/vite` plugin
    24	- **FFmpeg.wasm** — WebAssembly build of FFmpeg for all GIF processing
    25	- **Vite** — dev server and bundler
    26	
    27	## Browser Support
    28	
    29	Chrome, Edge, and Firefox. Safari is not supported (SharedArrayBuffer restrictions).
    30	
    31	## Getting Started
    32	
    33	```bash
    34	npm install
    35	npm run dev
    36	```
    37	
    38	Opens at `http://localhost:5173` with required COOP/COEP headers.
    39	
    40	### Production Build
    41	
    42	```bash
    43	npm run build
    44	npm run preview
    45	```
    46	
    47	## How It Works
    48	
    49	All processing happens client-side via FFmpeg.wasm:
    50	
    51	1. **Lazy loading** — FFmpeg.wasm (~25 MB) loads on first GIF drop, with a progress bar
    52	2. **IndexedDB caching** — WASM binary is cached after first download for instant reloads
    53	3. **Two-pass palette** — compress and Slack export use palettegen → paletteuse for quality
    54	4. **Operation replay undo** — stores operation history instead of full blobs, replays from original on undo
    55	
    56	## Deployment
    57	
    58	Deployed to GitHub Pages via Actions. The `coi-serviceworker` injects `Cross-Origin-Embedder-Policy` and `Cross-Origin-Opener-Policy` headers required by FFmpeg.wasm on static hosts.
